type TodoItem {
  id: ID!
  text: String!
  completed: Boolean!
}

type TodoListState {
  items: [TodoItem!]!
}

input AddTodoInput {
  id: ID!
  text: String!
}

args.content:
import type { TodoListTodosOperations } from "document-models/todo-list/v1";

export const todoListTodosOperations: TodoListTodosOperations = {
  addTodoOperation(state, action) {
    state.items.push({
      id: action.input.id,
      text: action.input.text,
      completed: false,
    });
  },
  toggleTodoOperation(state, action) {
    const item = state.items.find((i) => i.id === action.input.id);
    if (item) item.completed = !item.completed;
  },
  deleteTodoOperation(state, action) {
    const idx = state.items.findIndex((i) => i.id === action.input.id);
    if (idx !== -1) state.items.splice(idx, 1);
  },
};

import { useState } from "react";
import { DocumentToolbar } from "@powerhousedao/design-system/connect";
import { actions, useSelectedTodoListDocument } from "document-models/todo-list";

export default function Editor() {
  const [document, dispatch] = useSelectedTodoListDocument();
  const [newText, setNewText] = useState("");

  const items = document.state.global.items;

  const handleAdd = () => {
    const text = newText.trim();
    if (!text) return;
    dispatch(
      actions.addTodo({
        id: crypto.randomUUID(),
        text,
      }),
    );
    setNewText("");
  };

  return (
    <div className="mx-auto max-w-xl bg-white p-6">
      <DocumentToolbar />
      <h1 className="mb-4 text-2xl font-bold">{document.header.name}</h1>

      {/* Add item */}
      <div className="mb-4 flex gap-2">
        <input
          type="text"
          className="flex-1 rounded border px-3 py-2"
          placeholder="New todo…"
          value={newText}
          onChange={(e) => setNewText(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") handleAdd();
          }}
        />
        <button
          className="rounded bg-blue-600 px-4 py-2 text-white hover:bg-blue-700"
          onClick={handleAdd}
        >
          Add
        </button>
      </div>

      {/* List */}
      {items.length === 0 && (
        <p className="text-gray-400">No todos yet.</p>
      )}
      <ul className="space-y-2">
        {items.map((item) => (
          <li
            key={item.id}
            className="flex items-center justify-between rounded border px-3 py-2"
          >
            <div className="flex items-center gap-3">
              <input
                type="checkbox"
                checked={item.completed}
                onChange={() =>
                  dispatch(actions.toggleTodo({ id: item.id }))
                }
              />
              <span
                className={
                  item.completed ? "line-through text-gray-400" : ""
                }
              >
                {item.text}
              </span>
            </div>
            <button
              className="text-red-400 hover:text-red-600"
              onClick={() =>
                dispatch(actions.deleteTodo({ id: item.id }))
              }
            >
              ✕
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}
